'use strict';
const jobs = [
  {id:'ocean',title:'After-hours hotel cleanup',company:'The Ocean Club · Example employer',initial:'O',color:'',category:'hospitality',place:'Oceanfront district',time:'Night shift',tags:['Entry level','Uniform provided'],description:'The guests have checked out. Their life choices have not. Restore the lobby, service the pool deck, and get the hotel ready for another questionable weekend.',tasks:['Clean the lobby and pool deck.','Submit before-and-after shift evidence.','Complete a supervisor walkthrough.']},
  {id:'neon',title:'Post-party recovery crew',company:'Neon Palms · Example employer',initial:'N',color:'pink',category:'cleanup',place:'Entertainment district',time:'One-off cleanup',tags:['Crew of 3','Hazard pay proposed'],description:'Last night was legendary. This morning is a crime against upholstery. Bring a crew and return the venue to something its insurer would recognize.',tasks:['Clear the main floor and exterior.','Coordinate assignments with your crew.','Record completion for employer review.']},
  {id:'marina',title:'Marina maintenance contract',company:'Southside Marina · Example employer',initial:'M',color:'mint',category:'crew',place:'Marina district',time:'Recurring contract',tags:['Verified crew','Long-term'],description:'The yachts get the attention. Your crew keeps the waterfront running. A recurring maintenance contract built around reliable attendance and clean handovers.',tasks:['Agree a recurring schedule with the operator.','Maintain dockside communal areas.','Log each shift for approval.']}
];
const $ = selector => document.querySelector(selector);
const escapeHTML = value => String(value).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageAvailable=true;
function readLocal(key,fallback){try { const v=localStorage.getItem(key);return v?JSON.parse(v):fallback; } catch {storageAvailable=false;return fallback;}}
function writeLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageAvailable=false;toast('Browser storage is unavailable. Changes will last for this visit only.');return false;}}
const stored=readLocal('local6-saved',[]);
const saved=new Set(Array.isArray(stored)?stored.filter(id=>jobs.some(j=>j.id===id)):[]);
let activeFilter='all',showSaved=false;
function icon(name){return `<svg aria-hidden="true"><use href="#${name}"/></svg>`;}
function renderJobs(){
  const query=$('#job-search').value.trim().toLowerCase();
  const result=jobs.filter(job=>(activeFilter==='all'||job.category===activeFilter)&&(!showSaved||saved.has(job.id))&&`${job.title} ${job.company} ${job.place} ${job.tags.join(' ')}`.toLowerCase().includes(query));
  $('#saved-count').textContent=saved.size;
  $('#job-list').innerHTML=result.length?result.map(job=>`<article class="job-card"><div class="job-top"><span class="company-icon ${job.color}" aria-hidden="true">${job.initial}</span><div><h3>${job.title}</h3><div class="company-name">${job.company}</div></div></div><button class="job-save" data-save="${job.id}" aria-label="${saved.has(job.id)?'Unsave':'Save'} ${job.title}" aria-pressed="${saved.has(job.id)}">${saved.has(job.id)?'★':'☆'}</button><div class="job-meta"><span>${icon('pin')}${job.place}</span><span>${icon('brief')}${job.time}</span></div><div class="job-bottom"><div class="job-tags">${job.tags.map((tag,i)=>`<span class="${i===1&&job.id==='neon'?'priority':''}">${tag}</span>`).join('')}</div><button class="text-button" data-job="${job.id}">View contract <span>↗</span></button></div></article>`).join(''):'<div class="empty">No shifts match these filters.<br>Try another search or switch back to all shifts.</div>';
}
$('#job-search').addEventListener('input',renderJobs);
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{
 activeFilter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',b===button)});renderJobs();
}));
$('#saved-toggle').addEventListener('click',()=>{showSaved=!showSaved;$('#saved-toggle').setAttribute('aria-pressed',showSaved);renderJobs();});
$('#job-list').addEventListener('click',event=>{const save=event.target.closest('[data-save]');if(save){const id=save.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);writeLocal('local6-saved',[...saved]);renderJobs();const next=document.querySelector(`[data-save="${id}"]`);if(next)next.focus();return;}const item=event.target.closest('[data-job]');if(item)openJob(item.dataset.job);});
const dialog=$('#dialog');let returnFocus;
function openDialog(content){returnFocus=document.activeElement;$('#dialog-content').innerHTML=content;if(!dialog.open)dialog.showModal();document.body.classList.add('dialog-open');}
function closeDialog(){dialog.close();}
dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');returnFocus?.focus();});
$('.dialog-close').addEventListener('click',closeDialog);
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeDialog();}});
function heading(kicker,title){return `<div class="modal-kicker">${kicker}</div><h2 class="modal-title" id="dialog-title">${title}</h2>`;}
function openJob(id){const job=jobs.find(j=>j.id===id);if(!job)return;openDialog(`${heading('ILLUSTRATIVE CONTRACT',job.title)}<div class="modal-body"><strong>${job.company}</strong><p>${job.description}</p><ul class="modal-list">${job.tasks.map(t=>`<li>${t}</li>`).join('')}</ul><p><strong>Payment:</strong> To be agreed before accepting a live contract. No payout is attached to this example.</p></div><div class="modal-note">The jobs board is a concept preview. Hiring and applications open after the community server launches.</div><button class="button dark" id="modal-save">${saved.has(id)?'Remove from saved':'Save this example'}</button>`);$('#modal-save').addEventListener('click',()=>{saved.has(id)?saved.delete(id):saved.add(id);writeLocal('local6-saved',[...saved]);renderJobs();$('#modal-save').textContent=saved.has(id)?'Remove from saved':'Save this example';toast(saved.has(id)?'Example saved in this browser.':'Removed from saved examples.');});}
const charter=`GTA 6 JANITOR — LOCAL 6\nDRAFT UNION CHARTER\n\n1. PURPOSE\nAn independent Solana community building a roleplay janitors union, hiring network, and work-based reward program.\n\n2. FEES\nThe proposed policy routes 100% of collected project fees to the union treasury. No separate buyback allocation is proposed. The fee source, rate, routing, treasury address, and signers must be published before collection begins. Worker wages are separate from platform fees.\n\n3. MEMBERSHIP\nHolding $JANITOR will be required for DAO membership. The official mint, qualifying balance, snapshot rules, and governance process have not yet been published. No wallet is verified by this website.\n\n4. WORK\nVerification depends on completed trial shifts and evidence, not token balance. Every live contract must state duties, payment, approval criteria, and dispute terms before work begins.\n\n5. REWARDS\nProposed rewards depend on verified work and actual available treasury funds. Token ownership does not guarantee payments or investment returns. Allocations to rewards, server operations, and reserves require published rules and governance.\n\n6. ACCOUNTABILITY\nPublish treasury activity and approved spending. Use identity checks and work evidence to deter duplicate accounts and fake shifts. Provide a dispute and appeal process.\n\n7. LAUNCH\nThe token, DAO, treasury routing, and server are not live through this website. GTA 6 server expansion depends on supported tools and platform rules.\n\nIndependent fan community. Not affiliated with Rockstar Games or Take-Two. “Quit your job” is a meme, not career advice.\n`;
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function membership(){
 const prior=readLocal('local6-card',{});
 openDialog(`${heading('LOCAL 6 · MEMBERSHIP','Your first union card.')}<div class="modal-body">Make a provisional crew card while we build. Planned DAO access will require holding $JANITOR and verifying your wallet once the official mint and membership rules are published.</div><div class="modal-note">This is a browser-local collectible, not verified membership or DAO access. No token purchase or wallet connection is available here.</div><form id="card-form" class="modal-form"><label for="crew-name">Your crew name</label><input id="crew-name" name="name" required maxlength="28" placeholder="e.g. Mop Soprano" value="${escapeHTML(typeof prior.name==='string'?prior.name:'')}" autocomplete="nickname"><label for="crew-role">Your specialty</label><select name="role" id="crew-role"><option>Coastal cleanup</option><option>Night-shift specialist</option><option>Hospitality crew</option><option>Marina maintenance</option></select><button class="button dark" type="submit">Make my provisional card ${icon('arrow')}</button></form>`);
 $('#card-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const name=String(data.get('name')).trim();const role=String(data.get('role'));if(!name){$('#crew-name').setCustomValidity('Enter a crew name.');$('#crew-name').reportValidity();return;}const persisted=writeLocal('local6-card',{name,role});openDialog(`${heading('WELCOME TO THE BIT.','Looking employable.')}<div class="card-preview"><small>GTA 6 JANITOR · LOCAL 6</small><h3>${escapeHTML(name)}</h3><p>${escapeHTML(role)}</p><small>PROVISIONAL · NOT VERIFIED MEMBERSHIP</small></div><div class="modal-body">${persisted?'Your card is saved in this browser.':'Browser storage is unavailable. Download your card to keep it.'} Verification and holder access will open separately.</div><button class="button dark" id="download-card" style="margin-top:20px">Download union card ${icon('arrow')}</button>`);$('#download-card').addEventListener('click',()=>{const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="540" viewBox="0 0 900 540"><defs><linearGradient id="bg"><stop stop-color="#392440"/><stop offset="1" stop-color="#965578"/></linearGradient></defs><rect width="900" height="540" rx="32" fill="url(#bg)"/><rect x="25" y="25" width="850" height="490" rx="22" fill="none" stroke="#e0a4c5"/><g font-family="Arial,sans-serif"><text x="65" y="95" font-size="22" fill="#efbad2" letter-spacing="5">GTA 6 JANITOR / LOCAL 6</text><text x="65" y="245" font-size="${name.length>18?38:52}" font-weight="700" fill="#fff">${escapeHTML(name)}</text><text x="65" y="300" font-size="26" fill="#efd9e8">${escapeHTML(role)}</text><text x="65" y="440" font-size="16" fill="#efbad2" letter-spacing="2">PROVISIONAL · NOT VERIFIED MEMBERSHIP</text><text x="65" y="475" font-size="13" fill="#dfb8d1">Independent fan community. Not affiliated with Rockstar Games.</text></g></svg>`;download('local6-provisional-card.svg',svg,'image/svg+xml');});});
 $('#crew-name').addEventListener('input',()=>$('#crew-name').setCustomValidity(''));
}
function hire(){openDialog(`${heading('PUT THE MESS IN WRITING.','Build a hiring brief.')}<p class="modal-body">Plan a contract for your business. Download the brief to share with your future crew.</p><div class="modal-note">Planning tool only. This does not publish a job, book a worker, or send your details anywhere.</div><form id="hire-form" class="modal-form"><label for="business">Business / crew</label><input id="business" name="business" required maxlength="80" placeholder="Your business name"><label for="location">Location</label><input id="location" name="location" required maxlength="100" placeholder="District, venue, or server"><label for="work">What needs doing?</label><textarea id="work" name="work" required maxlength="1500" placeholder="Scope, timing, number of workers, and evidence of completion"></textarea><label for="budget">Proposed payment and currency</label><input id="budget" name="budget" required maxlength="100" placeholder="Specify amount, currency, and payment terms"><button class="button dark" type="submit">Download hiring brief ${icon('arrow')}</button></form>`);$('#hire-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);for(const field of event.currentTarget.querySelectorAll('input,textarea')){if(!field.value.trim()){field.setCustomValidity('Please enter a value.');field.reportValidity();field.addEventListener('input',()=>field.setCustomValidity(''),{once:true});return;}}download('local6-hiring-brief.txt',`LOCAL 6 — DRAFT HIRING BRIEF\n\nBusiness: ${data.get('business')}\nLocation: ${data.get('location')}\n\nWork requested:\n${data.get('work')}\n\nProposed payment: ${data.get('budget')}\n\nBefore accepting: agree duties, timing, payment, evidence, and dispute terms.\n\nDraft only. No booking or job submission has been made.\n`);toast('Hiring brief downloaded. No job was submitted.');});}
const actions={membership,hire,charter:()=>{openDialog(`${heading('LOCAL 6 · DRAFT CHARTER','A union worth showing up for.')}<div class="modal-body"><ul class="modal-list"><li><strong>100% of collected fees to the union.</strong> Publish every treasury address, allocation, and approved expense.</li><li><strong>Holders get a voice.</strong> Publish the token and qualification rules before opening DAO access.</li><li><strong>Work earns rewards.</strong> Verify shifts, prevent fake contracts, and provide a dispute process.</li><li><strong>Clear terms before every job.</strong> Agree payment, scope, and approval criteria in advance.</li></ul></div><div class="modal-note">Draft proposal. Server, governance, fee collection, and rewards are not live.</div><button class="button dark" id="download-charter">Download full charter ${icon('arrow')}</button>`);$('#download-charter').addEventListener('click',()=>download('local6-union-charter.txt',charter));},fund:()=>openDialog(`${heading('100% TO THE UNION.','One fund. Public accountability.')}<div class="modal-body"><p>The proposed policy puts <strong>100% of collected project fees</strong> into the union treasury, with no separate buyback allocation.</p><p>The union's planned uses are verified worker rewards, server operations, and a reserve for quieter periods. The split must be published and approved through governance before spending starts.</p><p>Workers' agreed wages remain separate from platform fees. Rewards can only be paid from funds actually available.</p></div><div class="modal-note">Treasury not live. Fee sources, rates, collection mechanism, wallet address, signers, and payout rules still need to be finalized. This page does not collect fees or promise payments.</div>`),status:()=>openDialog(`${heading('NO MYSTERY MINTS.','Where things stand.')}<div class="launch-list"><div><span>Website & concept</span><b>AVAILABLE</b></div><div><span>Token mint / launch link</span><b>NOT PUBLISHED</b></div><div><span>Discord / community invite</span><b>NOT PROVIDED</b></div><div><span>Holder verification & DAO</span><b>PLANNED</b></div><div><span>Treasury & fee routing</span><b>NOT LIVE</b></div><div><span>Roleplay server & hiring</span><b>PLANNED</b></div><div><span>GTA 6 server support</span><b>CONDITIONAL</b></div></div><p class="modal-note">This website never asks for a seed phrase or private key. There is currently no official token address linked here.</p>`)};
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button&&actions[button.dataset.action])actions[button.dataset.action]();});
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
let paused=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function updateMotion(){document.body.classList.toggle('motion-paused',paused);$('#motion-toggle').textContent=paused?'▶':'Ⅱ';$('#motion-toggle').setAttribute('aria-label',paused?'Resume conveyor animation':'Pause conveyor animation');}
$('#motion-toggle').addEventListener('click',()=>{paused=!paused;updateMotion();});updateMotion();
$('.menu-toggle').addEventListener('click',()=>{const open=$('.nav nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open);$('.menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');});
document.querySelectorAll('.nav nav a').forEach(link=>link.addEventListener('click',()=>{$('.nav nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Open navigation');document.querySelectorAll('.nav nav a').forEach(a=>a.classList.toggle('active',a===link));}));
$('#year').textContent=new Date().getFullYear();renderJobs();
